mapper.select:
Select *
from Paper p join student_information as si on p.student_number = si.student_number


        AND p.student_name LIKE CONCAT('%',#{studentName},'%')


        AND p.student_number LIKE CONCAT('%',#{studentNumber},'%')


        and si.classes = #{classes}


        and si.grade= #{grade}


        and si.major = #{major}


        and si.college = #{college}
